        tmp = 4 * lmuf * lmua * pow(z, -1) * CF * pow(NQCD, -1) + (- 4 * lmuf * lmua * pow(z, -1) * CF * NQCD) + (- 4 * lmuf * lmua * CF * pow(NQCD, -1)) + 4 * lmuf * lmua * CF * NQCD + 2 * lmuf * lmua * z * CF * pow(NQCD, -1) + (- 2 * lmuf * lmua * z * CF * NQCD) + 4 * lmuf * lmua * x * pow(z, -1) * CF * pow(NQCD, -1) + (- 4 * lmuf * lmua * x * pow(z, -1) * CF * NQCD) + (- 4 * lmuf * lmua * x * CF * pow(NQCD, -1)) + 4 * lmuf * lmua * x * CF * NQCD + 2 * lmuf * lmua * x * z * CF * pow(NQCD, -1) + (- 2 * lmuf * lmua * x * z * CF * NQCD);
